solutionCode.cpp:
#include <iostream>
using namespace std;

int main() {
    // De 7 en 7, de 7 jusqu'à 350 = 50 × 7.
    for (int i = 7; i <= 350; i += 7) {
        cout << i << "\n";
    }
    return 0;
}
